using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class HospitalVerify{static HospitalVerify(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("HospitalVerify.request"))return;File.Delete("HospitalVerify.request");try{var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);var front=new Vector3(-12,46,-351.9f);var target=new Vector3(-150,43,-351.9f);capture.Invoke(null,new object[]{s,front,target,"City-Hospital-Front-Day"});capture.Invoke(null,new object[]{s,new Vector3(-28,49,-275),target,"City-Hospital-Angled-Day"});var ctrl=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=ctrl.IsNight;try{ctrl.ApplyNight();capture.Invoke(null,new object[]{s,front,target,"City-Hospital-Front-Night"});}finally{if(night)ctrl.ApplyNight();else ctrl.ApplyDay();}var f=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>()).Single(g=>g.name=="Building_06_01_Material #26_0");File.AppendAllText("FinalEnvironmentRoadReview/CityHospitalUpgrade.txt","\nVERIFIED day/night front and angled previews, LOD levels="+f.GetComponent<LODGroup>().lodCount+" shaderErrors="+ShaderUtil.ShaderHasError(f.GetComponent<Renderer>().sharedMaterial.shader));}catch(Exception e){File.AppendAllText("FinalEnvironmentRoadReview/CityHospitalUpgrade.txt",e.ToString());Debug.LogException(e);}}}
